drop policy contests_manage_draft on public.contests;
create policy contests_insert_draft on public.contests for insert to authenticated with check (mandate_private.can_manage_election(election_id,array['owner','admin','election_manager']::public.organization_role[]) and exists(select 1 from public.elections e where e.id=election_id and e.status='draft'));
create policy contests_update_draft on public.contests for update to authenticated using (mandate_private.can_manage_election(election_id,array['owner','admin','election_manager']::public.organization_role[]) and exists(select 1 from public.elections e where e.id=election_id and e.status='draft')) with check (mandate_private.can_manage_election(election_id,array['owner','admin','election_manager']::public.organization_role[]) and exists(select 1 from public.elections e where e.id=election_id and e.status='draft'));
create policy contests_delete_draft on public.contests for delete to authenticated using (mandate_private.can_manage_election(election_id,array['owner','admin','election_manager']::public.organization_role[]) and exists(select 1 from public.elections e where e.id=election_id and e.status='draft'));
